CREATE TABLE IF NOT EXISTS notification (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  recipient_app_user_id UUID NOT NULL,
  notification_type_id UUID NOT NULL,
  notification_priority_id UUID NOT NULL,
  payload JSONB NOT NULL DEFAULT '{}',
  source_object_type STRING(40),
  source_object_ref UUID,
  dedupe_key STRING(100) NOT NULL,
  language_id UUID,
  seen_at TIMESTAMPTZ,
  read_at TIMESTAMPTZ,
  expires_at TIMESTAMPTZ NOT NULL DEFAULT now() + INTERVAL '180 days',
  CONSTRAINT pk_notification PRIMARY KEY (id),
  CONSTRAINT uq_notification_recipient_app_user_id_dedupe_key UNIQUE (recipient_app_user_id, dedupe_key),
  CONSTRAINT ck_notification_payload_size CHECK (length(payload::STRING) <= 2048),
  CONSTRAINT ck_notification_read_after_seen CHECK (read_at IS NULL OR seen_at IS NULL OR read_at >= seen_at),
  CONSTRAINT fk_notification_recipient_app_user_id FOREIGN KEY (recipient_app_user_id) REFERENCES app_user (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_notification_notification_type_id FOREIGN KEY (notification_type_id) REFERENCES notification_type (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_notification_notification_priority_id FOREIGN KEY (notification_priority_id) REFERENCES notification_priority (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_notification_language_id FOREIGN KEY (language_id) REFERENCES language (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  INDEX idx_notification_recipient_app_user_id_created_at (recipient_app_user_id, created_at DESC) STORING (notification_type_id, read_at),
  INDEX idx_notification_recipient_app_user_id_created_at_unread (recipient_app_user_id, created_at DESC) WHERE read_at IS NULL,
  INDEX idx_notification_expires_at (expires_at) USING HASH WITH (bucket_count = 16),
  INDEX idx_notification_created_at (created_at) USING HASH WITH (bucket_count = 16),
  INDEX idx_notification_notification_type_id (notification_type_id)
) WITH (ttl_expiration_expression = 'expires_at', ttl_job_cron = '@daily');
