  CONSTRAINT fk_support_ticket_attachment_media_type_id FOREIGN KEY (media_type_id) REFERENCES media_type (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_support_ticket_attachment_scan_status_id FOREIGN KEY (scan_status_id) REFERENCES scan_status (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
