CREATE TABLE IF NOT EXISTS job_alert_match (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  job_alert_run_id UUID NOT NULL,
  job_alert_preference_id UUID NOT NULL,
  job_requirement_id UUID NOT NULL,
  match_score DECIMAL(7,4) NOT NULL,
  rank_position INT2 NOT NULL,
  included_in_notification BOOL NOT NULL DEFAULT true,
  expires_at TIMESTAMPTZ NOT NULL DEFAULT now() + INTERVAL '120 days',
  CONSTRAINT pk_job_alert_match PRIMARY KEY (id),
  CONSTRAINT uq_job_alert_match_job_alert_preference_id_job_requirement_id UNIQUE (job_alert_preference_id, job_requirement_id),
  CONSTRAINT ck_job_alert_match_score CHECK (match_score BETWEEN 0 AND 100),
  CONSTRAINT ck_job_alert_match_rank CHECK (rank_position >= 1),
  CONSTRAINT fk_job_alert_match_job_alert_run_id FOREIGN KEY (job_alert_run_id) REFERENCES job_alert_run (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_job_alert_match_job_alert_preference_id FOREIGN KEY (job_alert_preference_id) REFERENCES job_alert_preference (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_job_alert_match_job_requirement_id FOREIGN KEY (job_requirement_id) REFERENCES job_requirement (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  INDEX idx_job_alert_match_expires_at (expires_at) USING HASH WITH (bucket_count = 16),
  INDEX idx_job_alert_match_created_at (created_at) USING HASH WITH (bucket_count = 16),
  INDEX idx_job_alert_match_job_alert_run_id (job_alert_run_id),
  INDEX idx_job_alert_match_job_requirement_id (job_requirement_id)
) WITH (ttl_expiration_expression = 'expires_at', ttl_job_cron = '@daily');
