  CONSTRAINT fk_referral_event_referrer_app_user_id FOREIGN KEY (referrer_app_user_id) REFERENCES app_user (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_referral_event_referred_app_user_id FOREIGN KEY (referred_app_user_id) REFERENCES app_user (id) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT fk_referral_event_referral_event_type_id FOREIGN KEY (referral_event_type_id) REFERENCES referral_event_type (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_referral_event_notification_channel_id FOREIGN KEY (notification_channel_id) REFERENCES notification_channel (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_referral_event_job_requirement_id FOREIGN KEY (job_requirement_id) REFERENCES job_requirement (id) ON DELETE SET NULL ON UPDATE RESTRICT,
  INDEX idx_referral_event_referrer_app_user_id_occurred_at (referrer_app_user_id, occurred_at DESC),
  INDEX idx_referral_event_referred_app_user_id (referred_app_user_id) WHERE referred_app_user_id IS NOT NULL,
  INDEX idx_referral_event_referral_code (referral_code),
  INDEX idx_referral_event_occurred_at (occurred_at) USING HASH WITH (bucket_count = 16),
